import sharp from 'sharp'; import fs from 'node:fs';
const files=fs.readdirSync('seq').filter(f=>f.endsWith('.jpg')).sort();
const T=300, COLS=7, ROWS=4, PER=COLS*ROWS;
for(let s=0;s*PER<files.length;s++){
  const batch=files.slice(s*PER,(s+1)*PER);
  const comps=[];
  for(let i=0;i<batch.length;i++){
    const buf=await sharp('seq/'+batch[i]).resize(T,T,{fit:'cover'}).jpeg().toBuffer();
    comps.push({input:buf,left:(i%COLS)*T,top:Math.floor(i/COLS)*T});
  }
  await sharp({create:{width:COLS*T,height:ROWS*T,channels:3,background:'#fff'}}).composite(comps).png().toFile(`sh-${s}.png`);
  console.log('sh-'+s, batch[0],'->',batch[batch.length-1]);
}
EOF
