import sharp from 'sharp'; import fs from 'node:fs';
export async function matte(file, W=900){
  const im = sharp(file).resize({width:W, withoutEnlargement:false});
  const {data,info} = await im.raw().toBuffer({resolveWithObject:true});
  const {width:w,height:h,channels:c}=info;
  const m = Math.max(4, Math.round(w*0.025));
  const alpha = Buffer.alloc(w*h);
  for(let y=0;y<h;y++){
    // background samples: median of left margin and right margin
    const lm=[],rm=[];
    for(let x=0;x<m;x++){const i=(y*w+x)*c; lm.push([data[i],data[i+1],data[i+2]]);}
    for(let x=w-m;x<w;x++){const i=(y*w+x)*c; rm.push([data[i],data[i+1],data[i+2]]);}
    const med=a=>{const s=[0,1,2].map(k=>a.map(p=>p[k]).sort((x,y)=>x-y)[a.length>>1]);return s;};
    const L=med(lm),R=med(rm);
    for(let x=0;x<w;x++){
      const t=x/(w-1); const bg=[L[0]+(R[0]-L[0])*t, L[1]+(R[1]-L[1])*t, L[2]+(R[2]-L[2])*t];
      const i=(y*w+x)*c;
      const d=Math.max(Math.abs(data[i]-bg[0]),Math.abs(data[i+1]-bg[1]),Math.abs(data[i+2]-bg[2]));
      alpha[y*w+x]= Math.min(255, Math.max(0, Math.round((d-8)*255/26)));
    }
  }
  return {alpha,w,h};
}
if(process.argv[2]){
  for(const f of process.argv.slice(2)){
    const {alpha,w,h}=await matte(`full/${f}.jpg`);
    const a=await sharp(alpha,{raw:{width:w,height:h,channels:1}}).blur(1.2).png().toBuffer();
    const base=await sharp(`full/${f}.jpg`).resize({width:w}).ensureAlpha().raw().toBuffer({resolveWithObject:true});
    const px=base.data; const ar=(await sharp(a).raw().toBuffer());
    for(let i=0;i<w*h;i++) px[i*4+3]=ar[i];
    await sharp(px,{raw:{width:w,height:h,channels:4}}).png().toFile(`cut-${f}.png`);
    console.log('cut-'+f);
  }
}
