  const ow=r-l, oh=bo-t, pad=Math.max(ow,oh)*0.09;
  l=Math.max(0,l-pad); t=Math.max(0,t-pad); r=Math.min(W,r+pad); bo=Math.min(H,bo+pad);
  const cw=Math.round(r-l), ch=Math.round(bo-t);
  const objW=Math.round(ow), objH=Math.round(oh);
