// Kilnwork — content. Every fact the shop owes, unchanged from the baseline,
// plus the media the page is built out of and the millimetres the shelf is
// drawn to. Dimensions are parsed from the `dims` string so there is exactly
// one source of truth for a piece's size.
import media from './media.json'

export const GLAZES = [
  { id: 'ash', name: 'Ash', note: 'A pale grey-green that breaks to white where the form turns.', img: 'glaze-ash' },
  { id: 'iron', name: 'Iron Red', note: 'Rust over a dark body, darker where the glaze pools.', img: 'glaze-iron' },
  { id: 'salt', name: 'Salt White', note: 'An off-white with a faint orange peel from the salt firing.', img: 'glaze-salt' },
]

// glazes: which of the three this piece is offered in. Not every form takes every glaze.
const RAW_PRODUCTS = [
  { id: 'mug-tall', name: 'Tall Mug', price: 34, dims: '95mm tall, 78mm across', capacity: '330ml', glazes: ['ash', 'iron', 'salt'], stock: 'in', dishwasher: true, microwave: true, img: 'tall-mug' },
  { id: 'mug-low', name: 'Low Mug', price: 32, dims: '72mm tall, 88mm across', capacity: '280ml', glazes: ['ash', 'salt'], stock: 'in', dishwasher: true, microwave: true, img: 'low-mug' },
  { id: 'cup-espresso', name: 'Espresso Cup', price: 22, dims: '55mm tall, 60mm across', capacity: '90ml', glazes: ['ash', 'iron', 'salt'], stock: 'in', dishwasher: true, microwave: true, img: 'espresso-cup' },
  { id: 'bowl-deep', name: 'Deep Bowl', price: 48, dims: '90mm tall, 190mm across', capacity: '1.1L', glazes: ['ash', 'iron'], stock: 'in', dishwasher: true, microwave: true, img: 'deep-bowl' },
  { id: 'bowl-shallow', name: 'Shallow Bowl', price: 42, dims: '48mm tall, 220mm across', capacity: '850ml', glazes: ['ash', 'salt'], stock: 'out', dishwasher: true, microwave: true, img: 'shallow-bowl' },
  { id: 'plate-side', name: 'Side Plate', price: 30, dims: '18mm tall, 200mm across', capacity: null, glazes: ['ash', 'iron', 'salt'], stock: 'in', dishwasher: true, microwave: true, img: 'side-plate' },
  { id: 'plate-dinner', name: 'Dinner Plate', price: 46, dims: '22mm tall, 275mm across', capacity: null, glazes: ['ash', 'salt'], stock: 'in', dishwasher: true, microwave: true, img: 'dinner-plate' },
  { id: 'jug', name: 'Pouring Jug', price: 68, dims: '160mm tall, 110mm across', capacity: '900ml', glazes: ['iron', 'salt'], stock: 'in', dishwasher: false, microwave: false, img: 'jug' },
  { id: 'vase', name: 'Bottle Vase', price: 94, dims: '280mm tall, 120mm across', capacity: null, glazes: ['ash', 'iron'], stock: 'out', dishwasher: false, microwave: false, img: 'vase' },
]

// The shelf is drawn to one scale. Each piece's largest stated measurement is
// what gets drawn at that scale, and it is the largest dimension of the object
// in its photograph that carries it.
export const PRODUCTS = RAW_PRODUCTS.map((p) => {
  const [, tall, across] = p.dims.match(/(\d+)mm tall, (\d+)mm across/)
  const m = media[p.img]
  const objPxW = m.objW * m.w
  const objPxH = m.objH * m.h
  return {
    ...p,
    mm: { tall: +tall, across: +across },
    maxMm: Math.max(+tall, +across),
    frame: m,
    // frame size, in millimetres, once the object's larger side is drawn to scale
    frameMm: (() => {
      const scale = Math.max(+tall, +across) / Math.max(objPxW, objPxH)
      return { w: m.w * scale, h: m.h * scale }
    })(),
  }
})

export const FIRING = ['fire-5', 'fire-1', 'fire-8', 'fire-3', 'fire-6', 'fire-4', 'fire-7', 'fire-2']

export const MAKING = [
  'Every piece is thrown on the wheel in the studio by the two of us. Nothing is slip cast and nothing is made anywhere else.',
  'Bisque fired to 1000°C, glazed by hand, then fired again to 1260°C over fourteen hours with a four hour hold.',
  'The glaze is mixed in small batches and each firing takes it differently, so no two pieces match exactly. The photographs are of pieces from the last firing, not of the one you will receive.',
  'When a piece sells out the restock takes about six weeks, because that is one full cycle of throwing, drying, and two firings.',
]

export const CARE = [
  'The foot of every piece is left unglazed, which is what a potter does and what marks a soft surface. Lift rather than slide on wood or a painted table.',
  'The jug and the vase are not dishwasher or microwave safe: the iron in the glaze reacts and the wall is too thin to take the thermal shock.',
  'Everything else goes in both. It will not craze, and the glaze does not contain lead.',
]

export const NOTES = [
  {
    quote:
      'I bought two tall mugs expecting them to be a bit precious and they have been the only two we use. The handle is the part I did not know I cared about.',
    name: 'Devan M.',
    bought: 'Two Tall Mugs in Ash',
    piece: 'mug-tall',
  },
  {
    quote:
      'The jug arrived with a mark on the shoulder where the glaze had run and I nearly sent it back. Six months later that is the reason I pick it up.',
    name: 'Priya S.',
    bought: 'Pouring Jug in Iron Red',
    piece: 'jug',
  },
]

export const SHIPPING = [
  'Shipping is free over £60 and £5.50 under it, within the UK.',
  'Thirty days to return anything unused, and you pay the return postage.',
  'If it arrives broken we replace it, and we do not ask for the pieces back. Send a photograph.',
]

// Every photograph on this page, with where it came from and what it is under.
export const CREDITS = [
  {
    group: 'The pieces, the glaze surfaces and the foot',
    line: 'Photographed stoneware from the open collections of the Cleveland Museum of Art (CC0) and The Metropolitan Museum of Art (CC0), and one mug from the Los Angeles County Museum of Art via Wikimedia Commons (public domain). Ash-, iron- and salt-glazed wares standing in for the pieces from our last firing. Cropped and graded here; nothing else altered.',
  },
  {
    group: 'The firing',
    line: 'Eight ash-glazed Shigaraki and Tokoname storage jars, Cleveland Museum of Art open access (CC0). One glaze, eight pots, no two alike.',
  },
]

export function glazeName(id) {
  return GLAZES.find((g) => g.id === id).name
}

import { useCallback, useEffect, useLayoutEffect, useMemo, useRef, useState } from 'react'
import { PRODUCTS, GLAZES, FIRING, MAKING, CARE, NOTES, SHIPPING, CREDITS, glazeName } from './data.js'

const img = (name, w) => `/media/${name}-${w}.webp`

function usePrefersReducedMotion() {
  const [reduced, setReduced] = useState(false)
  useEffect(() => {
    const q = window.matchMedia('(prefers-reduced-motion: reduce)')
    const on = () => setReduced(q.matches)
    on()
    q.addEventListener('change', on)
    return () => q.removeEventListener('change', on)
  }, [])
  return reduced
}

function useCoarse() {
  const [coarse, setCoarse] = useState(false)
  useEffect(() => {
    const q = window.matchMedia('(max-width: 860px)')
    const on = () => setCoarse(q.matches)
    on()
    q.addEventListener('change', on)
    return () => q.removeEventListener('change', on)
  }, [])
  return coarse
}

/* Regions resolve while they are on screen: the trigger is the region's top
   crossing 82% of the viewport, not its first pixel crossing the bottom. */
function useReveal() {
  const ref = useRef(null)
  useEffect(() => {
    const el = ref.current
    if (!el) return
    if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
      el.classList.add('is-in')
      return
    }
    const io = new IntersectionObserver(
      (entries) => {
        for (const e of entries) if (e.isIntersecting) { e.target.classList.add('is-in'); io.unobserve(e.target) }
      },
      { rootMargin: '0px 0px -18% 0px', threshold: 0 },
    )
    io.observe(el)
    return () => io.disconnect()
  }, [])
  return ref
}

function Reveal({ as: As = 'div', className = '', children, ...rest }) {
  const ref = useReveal()
  return (
    <As ref={ref} className={`reveal ${className}`} {...rest}>
      {children}
    </As>
  )
}

/* ---------------------------------------------------------------- the shelf */

function Piece({ p, selected, onSelect, registerNode }) {
  const out = p.stock === 'out'
  return (
    <button
      type="button"
      className={`piece${selected ? ' is-selected' : ''}${out ? ' is-out' : ''}`}
      style={{ '--fw': p.frameMm.w, '--fh': p.frameMm.h }}
      onClick={() => onSelect(p.id)}
      aria-pressed={selected}
      aria-label={`${p.name}, £${p.price}, ${p.dims}${out ? ', sold out' : ''}`}
    >
      <span className="piece-plate">
        <img
          ref={(n) => registerNode(p.id, n)}
          src={img(p.img, 700)}
          alt={`${p.name} — thrown stoneware`}
          width={p.frame.w}
          height={p.frame.h}
          loading="lazy"
          decoding="async"
        />
      </span>
      <span className="piece-tag">
        <span className="piece-name">{p.name}</span>
        <span className="piece-mm">{p.maxMm}mm</span>
      </span>
    </button>
  )
}

function Rule() {
  const ticks = []
  for (let mm = 0; mm <= 300; mm += 10) ticks.push(mm)
  return (
    <div className="rule" aria-hidden="true">
      <div className="rule-body" style={{ '--fh': 300 }}>
        {ticks.map((mm) => (
          <span key={mm} className={`tick${mm % 50 === 0 ? ' is-major' : ''}`} style={{ '--mm': mm }}>
            {mm % 50 === 0 ? <i>{mm}</i> : null}
          </span>
        ))}
      </div>
      <span className="rule-unit">mm</span>
    </div>
  )
}

/* -------------------------------------------------------------- the firing */

function Firing({ reduced, coarse }) {
  const sectionRef = useRef(null)
  const trackRef = useRef(null)
  const [p, setP] = useState(0)
  const still = !!(reduced || coarse)

  useEffect(() => {
    if (still) return
    const section = sectionRef.current
    const track = trackRef.current
    if (!section || !track) return
    let raf = 0
    const read = () => {
      raf = 0
      const rect = section.getBoundingClientRect()
      const span = rect.height - window.innerHeight
      const v = span > 0 ? Math.min(1, Math.max(0, -rect.top / span)) : 0
      setP(v)
      const travel = track.scrollWidth - window.innerWidth
      track.style.transform = `translate3d(${-(v * Math.max(0, travel))}px,0,0)`
    }
    const onScroll = () => { if (!raf) raf = requestAnimationFrame(read) }
    read()
    window.addEventListener('scroll', onScroll, { passive: true })
    window.addEventListener('resize', onScroll)
    return () => {
      if (raf) cancelAnimationFrame(raf)
      window.removeEventListener('scroll', onScroll)
      window.removeEventListener('resize', onScroll)
    }
  }, [still])

  const active = Math.min(FIRING.length - 1, Math.floor(p * FIRING.length + 0.0001))

  return (
    <section
      className={`firing${still ? ' is-still' : ''}`}
      id="firing"
      ref={sectionRef}
      aria-labelledby="firing-h"
    >
      <div className="firing-stick">
        <div className="firing-head">
          <h2 id="firing-h">
            One glaze. <em>Eight pots.</em>
          </h2>
          <p>
            The same ash glaze, mixed in one batch, on eight pots through one firing. Nothing about them was
            decided at the wheel.
          </p>
        </div>
        <div className="firing-track" ref={trackRef}>
          {FIRING.map((f, i) => (
            <figure key={f} className={`firing-pot${i === active ? ' is-active' : ''}`} style={{ '--i': i }}>
              <img
                src={img(f, i === 0 ? 1500 : 700)}
                srcSet={`${img(f, 700)} 700w, ${img(f, 1500)} 1500w`}
                sizes="(max-width: 860px) 74vw, 34vw"
                alt={`Ash-glazed stoneware jar, pot ${i + 1} of the firing`}
                loading={i < 2 ? 'eager' : 'lazy'}
                decoding="async"
              />
              <figcaption>
                <b>{String(i + 1).padStart(2, '0')}</b>
                <span>
                  {[
                    'the glaze ran and stopped short of the foot',
                    'it pooled in the throwing rings',
                    'the shoulder took most of the ash',
                    'one side stayed dry where it faced the wall',
                    'it went green where the flame turned',
                    'the neck is darker than the belly',
                    'a run reached the shelf and had to be ground off',
                    'this one came out almost white',
                  ][i]}
                </span>
              </figcaption>
            </figure>
          ))}
        </div>
        <div className="firing-foot">
          <div className="firing-count" aria-live="off">
            <b>{String(active + 1).padStart(2, '0')}</b>
            <span>/ {FIRING.length}</span>
          </div>
          <p className="firing-line">
            The glaze is mixed in small batches and each firing takes it differently, so{' '}
            <em>no two pieces match exactly.</em> The photographs are of pieces from the last firing, not of
            the one you will receive.
          </p>
        </div>
      </div>
    </section>
  )
}

/* ------------------------------------------------------------------- app */

export default function App() {
  const [bag, setBag] = useState([])
  const [selectedId, setSelectedId] = useState('mug-tall')
  const [glazeFocus, setGlazeFocus] = useState(null)
  const [bagOpen, setBagOpen] = useState(false)
  const reduced = usePrefersReducedMotion()
  const coarse = useCoarse()

  const shelfNodes = useRef({})
  const detailImgRef = useRef(null)
  const pendingFlip = useRef(null)
  const detailRef = useRef(null)

  const registerNode = useCallback((id, node) => {
    if (node) shelfNodes.current[id] = node
    else delete shelfNodes.current[id]
  }, [])

  const selected = PRODUCTS.find((p) => p.id === selectedId)
  const [glaze, setGlaze] = useState(selected.glazes[0])

  useEffect(() => {
    if (!selected.glazes.includes(glaze)) setGlaze(selected.glazes[0])
  }, [selectedId]) // eslint-disable-line react-hooks/exhaustive-deps

  /* The piece you were looking at becomes the piece you are looking at: the
     same image changes layout ownership from the shelf to the detail plate. */
  const selectPiece = useCallback(
    (id) => {
      const node = shelfNodes.current[id]
      if (node && !reduced) pendingFlip.current = node.getBoundingClientRect()
      setSelectedId(id)
    },
    [reduced],
  )

  useLayoutEffect(() => {
    const from = pendingFlip.current
    pendingFlip.current = null
    const el = detailImgRef.current
    if (!from || !el) return
    const to = el.getBoundingClientRect()
    if (!to.width || !to.height) return
    const dx = from.left + from.width / 2 - (to.left + to.width / 2)
    const dy = from.top + from.height / 2 - (to.top + to.height / 2)
    const s = from.width / to.width
    el.animate(
      [
        { transform: `translate(${dx}px, ${dy}px) scale(${s})`, opacity: 0.55 },
        { transform: 'translate(0,0) scale(1)', opacity: 1 },
      ],
      { duration: 460, easing: 'cubic-bezier(.2,.7,.2,1)' },
    )
  }, [selectedId])

  function add(product, glazeId) {
    if (product.stock === 'out') return
    setBag((lines) => {
      const at = lines.findIndex((l) => l.id === product.id && l.glaze === glazeId)
      if (at === -1)
        return [...lines, { id: product.id, name: product.name, glaze: glazeId, price: product.price, qty: 1 }]
      const next = lines.slice()
      next[at] = { ...next[at], qty: next[at].qty + 1 }
      return next
    })
    setBagOpen(true)
  }

  function remove(index) {
    setBag((lines) => lines.filter((_, i) => i !== index))
  }

  const total = bag.reduce((sum, l) => sum + l.price * l.qty, 0)
  const count = bag.reduce((n, l) => n + l.qty, 0)
  const toFree = Math.max(0, 60 - total)

  const jumpToPiece = useCallback(
    (id) => {
      selectPiece(id)
      const node = shelfNodes.current[id]
      if (node) {
        node.closest('.piece')?.scrollIntoView({ behavior: reduced ? 'auto' : 'smooth', inline: 'center', block: 'nearest' })
        document.getElementById('shelf')?.scrollIntoView({ behavior: reduced ? 'auto' : 'smooth', block: 'start' })
      }
    },
    [reduced, selectPiece],
  )

  const takesGlaze = useMemo(
    () => Object.fromEntries(GLAZES.map((g) => [g.id, PRODUCTS.filter((p) => p.glazes.includes(g.id))])),
    [],
  )

  return (
    <div className={`shop${glazeFocus ? ` glaze-${glazeFocus}` : ''}`}>
      <a className="skip" href="#shelf">Skip to the pieces</a>

      {/* ------------------------------------------------------- masthead */}
      <header className="masthead">
        <div className="masthead-in">
          <p className="wordmark">Kilnwork</p>
          <h1>
            Nine pieces, <em>thrown and fired here,</em> sold direct.
          </h1>
          <p className="lede">
            A two-person ceramics studio. Everything below is drawn to one scale, in millimetres, so you can
            see what you are buying before it is in your hands.
          </p>
          <a className="masthead-cue" href="#shelf">
            <span>The shelf</span>
            <svg width="13" height="26" viewBox="0 0 13 26" aria-hidden="true">
              <path d="M6.5 0v24M1 18.5l5.5 6 5.5-6" fill="none" stroke="currentColor" strokeWidth="1.3" />
            </svg>
          </a>
        </div>
      </header>

      {/* ---------------------------------------------------------- shelf */}
      <section className="shelf" id="shelf" aria-labelledby="shelf-h">
        <div className="shelf-head">
          <h2 id="shelf-h">The shelf</h2>
          <p>
            Drawn to scale against the rule. The tallest is 280mm; the smallest would sit inside it.
            <span className="hint"> Pick one up.</span>
          </p>
        </div>
        <div className="shelf-scroll">
          <div className="shelf-row">
            <Rule />
            {PRODUCTS.map((p) => (
              <Piece
                key={p.id}
                p={p}
                selected={p.id === selectedId}
                onSelect={selectPiece}
                registerNode={registerNode}
              />
            ))}
          </div>
          <div className="shelf-line" aria-hidden="true" />
        </div>
      </section>

      {/* --------------------------------------------------------- detail */}
      <section className="detail" id="piece" ref={detailRef} aria-labelledby="detail-h" aria-live="polite">
        <figure className="detail-plate">
          <img
            ref={detailImgRef}
            key={selected.id}
            src={img(selected.img, 1500)}
            srcSet={`${img(selected.img, 700)} 700w, ${img(selected.img, 1500)} 1500w`}
            sizes="(max-width: 860px) 92vw, 46vw"
            alt={`${selected.name}, ${selected.dims}`}
            width={selected.frame.w}
            height={selected.frame.h}
            decoding="async"
          />
          <figcaption>From the last firing. Yours will not be this one.</figcaption>
        </figure>

        <div className="detail-body">
          <h2 id="detail-h">{selected.name}</h2>
          <p className="detail-price">£{selected.price}</p>

          <dl className="spec">
            <div>
              <dt>Size</dt>
              <dd>{selected.dims}</dd>
            </div>
            {selected.capacity && (
              <div>
                <dt>Holds</dt>
                <dd>{selected.capacity}</dd>
              </div>
            )}
            <div>
              <dt>Dishwasher</dt>
              <dd className={selected.dishwasher ? 'yes' : 'no'}>
                {selected.dishwasher ? 'Safe' : 'Not safe'}
              </dd>
            </div>
            <div>
              <dt>Microwave</dt>
              <dd className={selected.microwave ? 'yes' : 'no'}>
                {selected.microwave ? 'Safe' : 'Not safe'}
              </dd>
            </div>
          </dl>

          <div className="pick">
            <p className="pick-label">
              Glaze
              <span>
                {selected.glazes.length === 3
                  ? 'Made in all three.'
                  : `This form is only made in ${selected.glazes.map(glazeName).join(' and ')}.`}
              </span>
            </p>
            <div className="pick-row" role="radiogroup" aria-label="Glaze">
              {GLAZES.map((g) => {
                const offered = selected.glazes.includes(g.id)
                return (
                  <button
                    key={g.id}
                    type="button"
                    role="radio"
                    aria-checked={offered && glaze === g.id}
                    disabled={!offered}
                    className={`swatch swatch-${g.id}${glaze === g.id && offered ? ' is-on' : ''}${offered ? '' : ' is-off'}`}
                    onClick={() => offered && setGlaze(g.id)}
                    title={offered ? g.note : `${selected.name} is not made in ${g.name}`}
                  >
                    <img src={img(g.img, 640)} alt="" loading="lazy" decoding="async" />
                    <span>{g.name}</span>
                    {!offered && <em>not in this form</em>}
                  </button>
                )
              })}
            </div>
          </div>

          {selected.stock === 'out' ? (
            <div className="sold-out">
              <p>
                <b>Sold out</b> — about six weeks
              </p>
              <p>
                That is one full cycle of throwing, drying, and two firings. We will not sell you one we have
                not made.
              </p>
            </div>
          ) : (
            <button className="add" type="button" onClick={() => add(selected, glaze)}>
              Add to bag — {selected.name} in {glazeName(glaze)}
              <span>£{selected.price}</span>
            </button>
          )}
        </div>
      </section>

      {/* --------------------------------------------------------- glazes */}
      <section className="glazes" id="glazes" aria-labelledby="glazes-h">
        <Reveal as="div" className="glazes-head">
          <h2 id="glazes-h">Three glazes</h2>
          <p>
            Shown at about ten times life size, off the pieces themselves. Each fires differently and no two
            pieces match exactly.
          </p>
        </Reveal>
        <div className="glaze-row">
          {GLAZES.map((g) => (
            <Reveal
              as="article"
              key={g.id}
              className={`glaze${glazeFocus === g.id ? ' is-focus' : ''}`}
              onMouseEnter={() => setGlazeFocus(g.id)}
              onMouseLeave={() => setGlazeFocus(null)}
            >
              <figure>
                <img
                  src={img(g.img, 1200)}
                  srcSet={`${img(g.img, 640)} 640w, ${img(g.img, 1200)} 1200w`}
                  sizes="(max-width: 860px) 92vw, 30vw"
                  alt={`${g.name} glaze, magnified`}
                  loading="lazy"
                  decoding="async"
                />
              </figure>
              <h3>{g.name}</h3>
              <p className="glaze-note">{g.note}</p>
              <ul className="glaze-list">
                {PRODUCTS.map((p) => {
                  const takes = p.glazes.includes(g.id)
                  return (
                    <li key={p.id} className={takes ? '' : 'is-struck'}>
                      <button type="button" onClick={() => takes && jumpToPiece(p.id)} disabled={!takes}>
                        {p.name}
                      </button>
                    </li>
                  )
                })}
              </ul>
              <p className="glaze-count">
                {takesGlaze[g.id].length} of the nine
              </p>
            </Reveal>
          ))}
        </div>
      </section>

      {/* ---------------------------------------------------------- firing */}
      <Firing reduced={reduced} coarse={coarse} />

      {/* ---------------------------------------------------------- making */}
      <section className="making" id="making" aria-labelledby="making-h">
        <Reveal className="making-in">
          <h2 id="making-h">How they are made</h2>
          <div className="figures">
            <div>
              <b>2</b>
              <span>of us, at the wheel</span>
            </div>
            <div>
              <b>1260°C</b>
              <span>the glaze firing, after a bisque at 1000°C</span>
            </div>
            <div>
              <b>14h</b>
              <span>with a four hour hold at the top</span>
            </div>
            <div>
              <b>6 weeks</b>
              <span>to make a sold-out piece again</span>
            </div>
          </div>
          <div className="making-text">
            {MAKING.map((line, i) => (
              <p key={i}>{line}</p>
            ))}
          </div>
        </Reveal>
      </section>

      {/* ------------------------------------------------------------ care */}
      <section className="care" id="care" aria-labelledby="care-h">
        <Reveal className="care-in">
          <figure className="care-foot">
            <img
              src={img('care-foot', 1200)}
              srcSet={`${img('care-foot', 640)} 640w, ${img('care-foot', 1200)} 1200w`}
              sizes="(max-width: 860px) 92vw, 42vw"
              alt="The unglazed foot ring of a bowl, where the bare clay meets the table"
              loading="lazy"
              decoding="async"
            />
            <figcaption>
              <span className="callout">The unglazed foot</span>
              This is the part that will mark a soft surface. Lift rather than slide on wood or a painted
              table.
            </figcaption>
          </figure>
          <div className="care-body">
            <h2 id="care-h">Living with them</h2>
            {CARE.map((line, i) => (
              <p key={i}>{line}</p>
            ))}
            <table className="care-table">
              <caption>Dishwasher and microwave, piece by piece</caption>
              <thead>
                <tr>
                  <th scope="col">Piece</th>
                  <th scope="col">Dishwasher</th>
                  <th scope="col">Microwave</th>
                </tr>
              </thead>
              <tbody>
                {PRODUCTS.map((p) => (
                  <tr key={p.id} className={p.dishwasher ? '' : 'is-warn'}>
                    <th scope="row">
                      <button type="button" onClick={() => jumpToPiece(p.id)}>{p.name}</button>
                    </th>
                    <td className={p.dishwasher ? 'yes' : 'no'}>{p.dishwasher ? 'Safe' : 'No'}</td>
                    <td className={p.microwave ? 'yes' : 'no'}>{p.microwave ? 'Safe' : 'No'}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </Reveal>
      </section>

      {/* ----------------------------------------------------------- notes */}
      <section className="notes" id="notes" aria-labelledby="notes-h">
        <h2 id="notes-h" className="visually-hidden">
          What buyers said
        </h2>
        <div className="notes-row">
          {NOTES.map((n) => {
            const p = PRODUCTS.find((x) => x.id === n.piece)
            return (
              <Reveal as="figure" key={n.name} className="note">
                <blockquote>{n.quote}</blockquote>
                <figcaption>
                  <b>{n.name}</b>
                  <button type="button" className="note-bought" onClick={() => jumpToPiece(n.piece)}>
                    <img src={img(p.img, 700)} alt="" loading="lazy" decoding="async" />
                    <span>{n.bought}</span>
                  </button>
                </figcaption>
              </Reveal>
            )
          })}
        </div>
      </section>

      {/* ----------------------------------------------------------- terms */}
      <section className="terms" id="terms" aria-labelledby="terms-h">
        <Reveal className="terms-in">
          <h2 id="terms-h">Getting it to you</h2>
          <ol className="terms-list">
            {SHIPPING.map((line, i) => (
              <li key={i}>
                <span className="terms-n">{String(i + 1).padStart(2, '0')}</span>
                <p>{line}</p>
              </li>
            ))}
          </ol>
          <div className={`threshold${total >= 60 ? ' is-met' : ''}`}>
            <div className="threshold-bar">
              <span style={{ width: `${Math.min(100, (total / 60) * 100)}%` }} />
              <i>£60</i>
            </div>
            <p>
              {total === 0
                ? 'Free shipping over £60. Your bag is empty.'
                : total >= 60
                  ? `£${total} in the bag — shipping is free.`
                  : `£${total} in the bag. £${toFree} more and shipping is free.`}
            </p>
          </div>
        </Reveal>
      </section>

      {/* -------------------------------------------------------- colophon */}
      <footer className="colophon">
        <div className="colophon-in">
          <p className="wordmark">Kilnwork</p>
          <p className="colophon-line">A two-person ceramics studio. Nine pieces, thrown and fired here, sold direct.</p>
          <div className="credits">
            {CREDITS.map((c) => (
              <p key={c.group}>
                <b>{c.group}.</b> {c.line}
              </p>
            ))}
          </div>
        </div>
      </footer>

      {/* ------------------------------------------------------------- bag */}
      <div className={`bag${bagOpen ? ' is-open' : ''}`}>
        <button
          type="button"
          className="bag-tab"
          onClick={() => setBagOpen((o) => !o)}
          aria-expanded={bagOpen}
          aria-controls="bag-panel"
        >
          <span className="bag-word">Bag</span>
          <span className="bag-count">{count}</span>
          <span className="bag-total">£{total}</span>
        </button>
        <div className="bag-panel" id="bag-panel" hidden={!bagOpen}>
          {bag.length === 0 ? (
            <p className="bag-empty">Nothing in the bag yet.</p>
          ) : (
            <>
              <ul className="bag-lines">
                {bag.map((l, i) => {
                  const p = PRODUCTS.find((x) => x.id === l.id)
                  return (
                    <li key={`${l.id}-${l.glaze}`}>
                      <img src={img(p.img, 700)} alt="" loading="lazy" decoding="async" />
                      <span className="bag-name">
                        {l.name} <em>in {glazeName(l.glaze)}</em>
                      </span>
                      <span className="bag-qty">
                        {l.qty} × £{l.price}
                      </span>
                      <span className="bag-sum">£{l.price * l.qty}</span>
                      <button type="button" onClick={() => remove(i)} aria-label={`Remove ${l.name} in ${glazeName(l.glaze)}`}>
                        Remove
                      </button>
                    </li>
                  )
                })}
              </ul>
              <p className="bag-foot">
                <span>Total</span>
                <b>£{total}</b>
              </p>
              <p className="bag-ship">
                {total >= 60 ? 'Shipping is free.' : `£${toFree} more for free shipping.`}
              </p>
            </>
          )}
        </div>
      </div>
    </div>
  )
}

@import url('https://api.fontshare.com/v2/css?f%5B%5D=zodiak@400,700&f%5B%5D=switzer@400,500,600&display=swap');

/* Colours are sampled off the glazes themselves: the ash macro's olive, the
   iron macro's rust over its near-black body, the salt macro's off-white. */
:root {
  --kiln: #171310;
  --kiln-2: #1f1a15;
  --kiln-3: #292118;
  --paper: #e7dfd1;
  --paper-2: #ded4c3;
  --ink: #1a1511;
  --ash: #90805b;
  --ash-lit: #b3a37a;
  --iron: #a8542c;
  --iron-lit: #c9713f;
  --salt: #d5c3ad;
  --dim: #9a8e7f;
  --dim-dark: #6d6459;
  --hair: rgba(213, 195, 173, 0.19);
  --hair-ink: rgba(26, 21, 17, 0.18);
  --serif: 'Zodiak', 'Iowan Old Style', Georgia, serif;
  --sans: 'Switzer', 'Inter', system-ui, -apple-system, sans-serif;
  --pxmm: 1.34;
  --ease: cubic-bezier(0.2, 0.7, 0.2, 1);
  --t: 150ms;
}

* { box-sizing: border-box; }

html { scroll-behavior: smooth; }
@media (prefers-reduced-motion: reduce) { html { scroll-behavior: auto; } }

body {
  margin: 0;
  background: var(--kiln);
  color: var(--salt);
  font-family: var(--sans);
  font-size: 16px;
  line-height: 1.55;
  -webkit-font-smoothing: antialiased;
  overflow-x: hidden;
}

img { display: block; max-width: 100%; height: auto; }

h1, h2, h3 { font-family: var(--serif); font-weight: 400; letter-spacing: -0.012em; margin: 0; }
h1 em, h2 em, .firing-line em { font-style: italic; color: var(--ash-lit); }
p { margin: 0; }

.visually-hidden {
  position: absolute; width: 1px; height: 1px; overflow: hidden;
  clip: rect(0 0 0 0); clip-path: inset(50%); white-space: nowrap;
}

.skip {
  position: absolute; left: 16px; top: -60px; z-index: 60;
  background: var(--salt); color: var(--kiln); padding: 10px 16px; border-radius: 2px;
  font: 500 14px var(--sans); text-decoration: none; transition: top var(--t) var(--ease);
}
.skip:focus { top: 16px; }

/* ---------------------------------------------- one interaction grammar */

button { font: inherit; color: inherit; }

a, button {
  transition: color var(--t) var(--ease), background-color var(--t) var(--ease),
    border-color var(--t) var(--ease), transform var(--t) var(--ease), opacity var(--t) var(--ease),
    box-shadow var(--t) var(--ease);
}
:where(a, button, [tabindex]):focus-visible {
  outline: 2px solid var(--ash-lit);
  outline-offset: 3px;
  border-radius: 1px;
}
:where(button):not(:disabled):active { transform: translateY(1px); }

.reveal { opacity: 0; transform: translateY(16px); transition: opacity 620ms var(--ease), transform 620ms var(--ease); }
.reveal.is-in { opacity: 1; transform: none; }
@media (prefers-reduced-motion: reduce) { .reveal { opacity: 1; transform: none; transition: none; } }

/* -------------------------------------------------------------- masthead */

.masthead {
  padding: clamp(56px, 9vw, 120px) 0 clamp(30px, 4vw, 52px);
  border-bottom: 1px solid var(--hair);
}
.masthead-in { max-width: 1360px; margin: 0 auto; padding: 0 clamp(20px, 4vw, 56px); }

.wordmark {
  font-family: var(--sans);
  font-weight: 600;
  font-size: 13px;
  letter-spacing: 0.3em;
  text-transform: uppercase;
  color: var(--ash-lit);
}

.masthead h1 {
  margin: clamp(20px, 4vw, 44px) 0 0;
  font-size: clamp(38px, 7.2vw, 92px);
  line-height: 0.98;
  max-width: 15ch;
  text-wrap: balance;
}
.lede {
  margin-top: clamp(18px, 2.4vw, 28px);
  max-width: 52ch;
  color: var(--dim);
  font-size: clamp(15px, 1.25vw, 18px);
}
.masthead-cue {
  display: inline-flex; align-items: center; gap: 12px;
  margin-top: clamp(28px, 4vw, 48px);
  color: var(--salt); text-decoration: none;
  font-size: 13px; letter-spacing: 0.16em; text-transform: uppercase;
  padding-bottom: 6px; border-bottom: 1px solid var(--hair);
}
.masthead-cue:hover { color: var(--ash-lit); border-bottom-color: var(--ash-lit); }
.masthead-cue svg { transition: transform 400ms var(--ease); }
.masthead-cue:hover svg { transform: translateY(4px); }

/* ----------------------------------------------------------------- shelf */

.shelf { padding: clamp(46px, 6vw, 86px) 0 0; }
.shelf-head {
  max-width: 1360px; margin: 0 auto clamp(26px, 4vw, 48px);
  padding: 0 clamp(20px, 4vw, 56px);
  display: flex; flex-wrap: wrap; align-items: baseline; gap: 10px 32px;
}
.shelf-head h2 { font-size: clamp(24px, 2.6vw, 34px); }
.shelf-head p { color: var(--dim); font-size: 15px; max-width: 58ch; }
.hint { color: var(--ash-lit); }

.shelf-scroll {
  position: relative;
  overflow-x: auto;
  overflow-y: hidden;
  scrollbar-width: thin;
  scrollbar-color: var(--ash) transparent;
  padding: 0 clamp(20px, 4vw, 56px);
  -webkit-overflow-scrolling: touch;
}
.shelf-scroll::-webkit-scrollbar { height: 6px; }
.shelf-scroll::-webkit-scrollbar-thumb { background: var(--dim-dark); border-radius: 3px; }

.shelf-row {
  display: flex;
  align-items: flex-end;
  gap: clamp(14px, 1.8vw, 34px);
  width: max-content;
  padding-bottom: 2px;
}

.shelf-line {
  position: sticky; left: 0;
  height: 1px; background: var(--hair);
  margin: 0 clamp(20px, 4vw, 56px);
}

/* the rule: 300mm of real millimetres, sticky so it stays readable */
.rule {
  position: sticky; left: 0; z-index: 3;
  align-self: flex-end;
  display: flex; align-items: flex-end; gap: 8px;
  padding-right: 14px;
  background: linear-gradient(90deg, var(--kiln) 62%, rgba(23, 19, 16, 0));
}
.rule-body {
  position: relative;
  height: calc(var(--fh) * var(--pxmm) * 1px);
  width: 46px;
  border-left: 1px solid var(--hair);
}
.tick {
  position: absolute; left: 0; bottom: calc(var(--mm) * var(--pxmm) * 1px);
  width: 7px; height: 1px; background: var(--hair);
}
.tick.is-major { width: 15px; background: rgba(213, 195, 173, 0.4); }
.tick i {
  position: absolute; left: 19px; top: -8px;
  font-style: normal; font-size: 10px; letter-spacing: 0.08em;
  color: var(--dim-dark);
}
.rule-unit {
  font-size: 10px; letter-spacing: 0.2em; text-transform: uppercase;
  color: var(--dim-dark); padding-bottom: 2px;
}

.piece {
  appearance: none; background: none; border: 0; padding: 0;
  display: flex; flex-direction: column; justify-content: flex-end; align-items: center;
  cursor: pointer;
  filter: saturate(0.92) brightness(0.9);
  transition: filter 260ms var(--ease), transform 260ms var(--ease);
}
.piece-plate { display: block; position: relative; }
.piece img {
  height: calc(var(--fh) * var(--pxmm) * 1px);
  width: calc(var(--fw) * var(--pxmm) * 1px);
  object-fit: cover;
  border-radius: 1px;
}
.piece:hover { filter: saturate(1) brightness(1.06); transform: translateY(-3px); }
.piece.is-selected { filter: saturate(1) brightness(1.12); }
.piece.is-selected .piece-plate::after {
  content: ''; position: absolute; inset: -6px -6px -8px;
  border: 1px solid var(--ash-lit); border-radius: 2px;
  pointer-events: none;
}
.piece.is-out { filter: saturate(0.34) brightness(0.62); }
.piece.is-out:hover { filter: saturate(0.45) brightness(0.72); }

.piece-tag {
  display: flex; flex-direction: column; align-items: center; gap: 1px;
  margin-top: 12px; min-height: 34px;
}
.piece-name { font-size: 12px; letter-spacing: 0.05em; white-space: nowrap; }
.piece-mm { font-size: 10px; letter-spacing: 0.1em; color: var(--dim-dark); }
.piece.is-selected .piece-name { color: var(--ash-lit); }

/* ---------------------------------------------------------------- detail */

.detail {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  gap: clamp(26px, 5vw, 76px);
  align-items: center;
  max-width: 1360px; margin: 0 auto;
  padding: clamp(40px, 6vw, 88px) clamp(20px, 4vw, 56px) clamp(56px, 8vw, 110px);
}
.detail-plate { margin: 0; }
.detail-plate img { width: 100%; border-radius: 2px; }
.detail-plate figcaption {
  margin-top: 12px; font-size: 12px; color: var(--dim-dark); letter-spacing: 0.03em;
}
.detail-body h2 { font-size: clamp(30px, 4vw, 54px); line-height: 1.02; }
.detail-price {
  font-family: var(--serif);
  font-size: clamp(22px, 2.2vw, 30px);
  color: var(--ash-lit);
  margin-top: 6px;
}

.spec {
  display: grid; grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0; margin: clamp(22px, 3vw, 34px) 0 0;
  border-top: 1px solid var(--hair);
}
.spec > div { padding: 13px 0; border-bottom: 1px solid var(--hair); }
.spec > div:nth-child(odd) { padding-right: 18px; }
.spec dt { font-size: 11px; letter-spacing: 0.16em; text-transform: uppercase; color: var(--dim-dark); }
.spec dd { margin: 3px 0 0; font-size: 15px; }
.spec dd.no, .care-table td.no { color: var(--iron-lit); }

.pick { margin-top: clamp(22px, 3vw, 32px); }
.pick-label { font-size: 11px; letter-spacing: 0.16em; text-transform: uppercase; color: var(--dim-dark); }
.pick-label span {
  display: block; margin-top: 5px;
  font-size: 13px; letter-spacing: 0; text-transform: none; color: var(--dim);
}
.pick-row { display: flex; gap: 10px; margin-top: 13px; flex-wrap: wrap; }

.swatch {
  appearance: none; border: 1px solid var(--hair); background: none;
  padding: 0 0 9px; border-radius: 2px; cursor: pointer;
  flex: 1 1 130px; min-width: 118px; text-align: left; overflow: hidden;
}
.swatch img { width: 100%; height: 62px; object-fit: cover; }
.swatch span { display: block; padding: 8px 10px 0; font-size: 13px; }
.swatch em { display: block; padding: 1px 10px 0; font-size: 11px; font-style: normal; color: var(--dim-dark); }
.swatch:not(:disabled):hover { border-color: var(--ash-lit); }
.swatch.is-on { border-color: var(--salt); background: var(--kiln-2); }
.swatch.is-on span { color: var(--salt); }
.swatch.is-off { cursor: not-allowed; opacity: 0.4; }
.swatch.is-off img { filter: grayscale(1) brightness(0.7); }
.swatch.is-off span { text-decoration: line-through; text-decoration-color: var(--iron); }

.add {
  display: flex; align-items: baseline; justify-content: space-between; gap: 18px;
  width: 100%; margin-top: clamp(22px, 3vw, 30px);
  padding: 17px 20px; border: 0; border-radius: 2px;
  background: var(--salt); color: var(--kiln);
  font-size: 15px; font-weight: 500; cursor: pointer; text-align: left;
}
.add span { font-family: var(--serif); font-size: 18px; }
.add:hover { background: #efe2d1; }

.sold-out {
  margin-top: clamp(22px, 3vw, 30px); padding: 18px 20px;
  border: 1px solid var(--hair); border-left: 2px solid var(--iron); border-radius: 2px;
  background: rgba(168, 84, 44, 0.06);
}
.sold-out p + p { margin-top: 7px; font-size: 14px; color: var(--dim); }
.sold-out b { color: var(--iron-lit); }

/* ---------------------------------------------------------------- glazes */

.glazes {
  background: var(--kiln-2);
  border-top: 1px solid var(--hair);
  padding: clamp(52px, 7vw, 104px) clamp(20px, 4vw, 56px);
}
.glazes-head { max-width: 1360px; margin: 0 auto clamp(30px, 4vw, 52px); }
.glazes-head h2 { font-size: clamp(26px, 3vw, 40px); }
.glazes-head p { margin-top: 10px; color: var(--dim); max-width: 56ch; }

.glaze-row {
  max-width: 1360px; margin: 0 auto;
  display: grid; grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: clamp(16px, 2.4vw, 38px);
}
.glaze { transition: opacity 320ms var(--ease); }
.glaze figure { margin: 0; overflow: hidden; border-radius: 2px; }
.glaze figure img {
  width: 100%; aspect-ratio: 4 / 3; object-fit: cover;
  transition: transform 700ms var(--ease);
}
.glaze:hover figure img { transform: scale(1.045); }
.glaze h3 { margin-top: 16px; font-size: 22px; }
.glaze-note { margin-top: 6px; color: var(--dim); font-size: 14px; min-height: 3em; }

.glaze-list { list-style: none; margin: 16px 0 0; padding: 0; border-top: 1px solid var(--hair); }
.glaze-list li { border-bottom: 1px solid var(--hair); }
.glaze-list button {
  appearance: none; background: none; border: 0; width: 100%; text-align: left;
  padding: 7px 0; font-size: 13px; color: var(--salt); cursor: pointer;
}
.glaze-list button:not(:disabled):hover { color: var(--ash-lit); padding-left: 5px; }
.glaze-list .is-struck button {
  color: var(--dim-dark); cursor: not-allowed;
  text-decoration: line-through; text-decoration-color: var(--iron);
  text-decoration-thickness: 1px;
}
.glaze-count { margin-top: 11px; font-size: 11px; letter-spacing: 0.14em; text-transform: uppercase; color: var(--dim-dark); }

/* the whole route answers the glaze under the pointer */
.shop.glaze-ash .glaze:not(.is-focus),
.shop.glaze-iron .glaze:not(.is-focus),
.shop.glaze-salt .glaze:not(.is-focus) { opacity: 0.5; }

/* ---------------------------------------------------------------- firing */

.firing { position: relative; height: 420vh; background: #100d0b; }
.firing-stick {
  position: sticky; top: 0; height: 100vh;
  display: flex; flex-direction: column; justify-content: space-between;
  overflow: hidden; padding: clamp(26px, 4vh, 52px) 0;
}
.firing-head, .firing-foot { padding: 0 clamp(20px, 4vw, 56px); max-width: 1360px; margin: 0 auto; width: 100%; }
.firing-head h2 { font-size: clamp(26px, 3.4vw, 46px); }
.firing-head p { margin-top: 9px; color: var(--dim); max-width: 48ch; font-size: 15px; }

.firing-track {
  display: flex; align-items: center; gap: clamp(24px, 4vw, 72px);
  padding: 0 clamp(20px, 4vw, 56px);
  width: max-content;
  will-change: transform;
}
.firing-pot { margin: 0; width: clamp(230px, 30vw, 420px); }
.firing-pot img {
  width: 100%;
  height: clamp(220px, 42vh, 460px);
  object-fit: contain;
  filter: brightness(0.62) saturate(0.8);
  transition: filter 480ms var(--ease);
}
.firing-pot.is-active img { filter: brightness(1.06) saturate(1); }
.firing-pot figcaption {
  display: flex; gap: 10px; margin-top: 14px;
  font-size: 12px; color: var(--dim-dark); line-height: 1.4;
  opacity: 0.35; transition: opacity 480ms var(--ease), color 480ms var(--ease);
}
.firing-pot.is-active figcaption { opacity: 1; color: var(--dim); }
.firing-pot figcaption b { font-family: var(--serif); color: var(--ash-lit); }

.firing-foot { display: flex; align-items: flex-end; gap: clamp(20px, 3vw, 44px); flex-wrap: wrap; }
.firing-count { display: flex; align-items: baseline; gap: 6px; font-family: var(--serif); }
.firing-count b { font-size: clamp(34px, 4.4vw, 62px); line-height: 1; color: var(--salt); }
.firing-count span { font-size: 15px; color: var(--dim-dark); }
.firing-line { flex: 1 1 380px; color: var(--dim); font-size: 15px; max-width: 62ch; }

.firing.is-still { height: auto; }
.firing.is-still .firing-stick { position: static; height: auto; gap: clamp(22px, 4vw, 40px); }
.firing.is-still .firing-track {
  width: auto; overflow-x: auto; scroll-snap-type: x mandatory;
  transform: none !important; padding-bottom: 10px;
}
.firing.is-still .firing-pot { scroll-snap-align: center; flex: 0 0 auto; }
.firing.is-still .firing-pot img { filter: none; height: clamp(240px, 44vh, 380px); }
.firing.is-still .firing-pot figcaption { opacity: 1; color: var(--dim); }
.firing.is-still .firing-count { display: none; }

/* ---------------------------------------------------------------- making */

.making { background: var(--paper); color: var(--ink); padding: clamp(56px, 8vw, 118px) clamp(20px, 4vw, 56px); }
.making-in { max-width: 1360px; margin: 0 auto; }
.making h2 { font-size: clamp(28px, 3.6vw, 48px); max-width: 16ch; }

.figures {
  display: grid; grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: clamp(14px, 2vw, 30px);
  margin: clamp(30px, 4vw, 52px) 0 clamp(30px, 4vw, 48px);
  border-top: 1px solid var(--hair-ink);
}
.figures > div { padding-top: 16px; border-right: 1px solid var(--hair-ink); padding-right: 16px; }
.figures > div:last-child { border-right: 0; }
.figures b {
  display: block; font-family: var(--serif); font-weight: 400;
  font-size: clamp(30px, 4.4vw, 60px); line-height: 1;
}
.figures span { display: block; margin-top: 8px; font-size: 13px; color: #5d5348; max-width: 22ch; }

.making-text { columns: 2; column-gap: clamp(24px, 4vw, 62px); max-width: 100ch; }
.making-text p { break-inside: avoid; margin-bottom: 15px; font-size: 15.5px; color: #463e35; }

/* ------------------------------------------------------------------ care */

.care { background: var(--paper-2); color: var(--ink); padding: clamp(52px, 7vw, 104px) clamp(20px, 4vw, 56px); }
.care-in {
  max-width: 1360px; margin: 0 auto;
  display: grid; grid-template-columns: minmax(0, 0.85fr) minmax(0, 1fr);
  gap: clamp(28px, 5vw, 72px); align-items: start;
}
.care-foot { margin: 0; }
.care-foot img { width: 100%; border-radius: 2px; }
.care-foot figcaption { margin-top: 14px; font-size: 14px; color: #4d443b; max-width: 42ch; }
.callout {
  display: block; margin-bottom: 5px;
  font-family: var(--sans); font-size: 11px; letter-spacing: 0.18em; text-transform: uppercase;
  color: var(--iron);
}
.care-body h2 { font-size: clamp(26px, 3.2vw, 42px); }
.care-body > p { margin-top: 14px; font-size: 15.5px; color: #463e35; max-width: 60ch; }

.care-table { width: 100%; border-collapse: collapse; margin-top: clamp(26px, 3vw, 38px); }
.care-table caption {
  text-align: left; font-size: 11px; letter-spacing: 0.16em; text-transform: uppercase;
  color: #6d6459; padding-bottom: 9px;
}
.care-table th, .care-table td { text-align: left; padding: 9px 10px 9px 0; border-bottom: 1px solid var(--hair-ink); font-weight: 400; font-size: 14px; }
.care-table thead th { font-size: 11px; letter-spacing: 0.1em; text-transform: uppercase; color: #6d6459; }
.care-table td { text-align: right; padding-right: 0; width: 22%; }
.care-table tbody th button {
  appearance: none; background: none; border: 0; padding: 0; cursor: pointer;
  font-size: 14px; color: var(--ink); text-align: left;
  border-bottom: 1px solid transparent;
}
.care-table tbody th button:hover { border-bottom-color: var(--iron); color: var(--iron); }
.care-table td.yes { color: #5d5348; }
.care-table td.no { color: var(--iron); }
.care-table tr.is-warn th button { color: var(--iron); }

/* ----------------------------------------------------------------- notes */

.notes { background: var(--paper-2); color: var(--ink); padding: 0 clamp(20px, 4vw, 56px) clamp(56px, 8vw, 110px); }
.notes-row {
  max-width: 1360px; margin: 0 auto;
  display: grid; grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: clamp(22px, 4vw, 62px);
}
.note { margin: 0; padding-top: clamp(24px, 3vw, 40px); border-top: 1px solid var(--hair-ink); }
.note blockquote {
  margin: 0; font-family: var(--serif);
  font-size: clamp(19px, 1.9vw, 26px); line-height: 1.34; color: #2b2520;
  text-wrap: pretty;
}
.note figcaption { margin-top: 20px; display: flex; flex-wrap: wrap; align-items: center; gap: 10px 18px; }
.note figcaption b { font-weight: 500; font-size: 14px; }
.note-bought {
  display: inline-flex; align-items: center; gap: 10px;
  appearance: none; background: none; border: 0; padding: 5px 10px 5px 5px; cursor: pointer;
  border: 1px solid var(--hair-ink); border-radius: 999px;
  font-size: 13px; color: #4d443b;
}
.note-bought img { width: 28px; height: 28px; border-radius: 50%; object-fit: cover; }
.note-bought:hover { border-color: var(--iron); color: var(--iron); }

/* ----------------------------------------------------------------- terms */

.terms { background: var(--kiln); padding: clamp(52px, 7vw, 100px) clamp(20px, 4vw, 56px); }
.terms-in {
  max-width: 1360px; margin: 0 auto;
  display: grid; grid-template-columns: minmax(0, 1fr) minmax(280px, 0.62fr);
  gap: clamp(26px, 5vw, 74px); align-items: start;
}
.terms h2 { font-size: clamp(24px, 3vw, 38px); grid-column: 1 / -1; }
.terms-list { list-style: none; margin: clamp(20px, 3vw, 30px) 0 0; padding: 0; }
.terms-list li { display: flex; gap: 18px; padding: 15px 0; border-top: 1px solid var(--hair); }
.terms-n { font-family: var(--serif); font-size: 13px; color: var(--ash-lit); padding-top: 2px; }
.terms-list p { font-size: 15.5px; max-width: 52ch; }

.threshold {
  margin-top: clamp(20px, 3vw, 30px); padding: 20px;
  border: 1px solid var(--hair); border-radius: 2px; background: var(--kiln-2);
}
.threshold-bar {
  position: relative; height: 3px; background: rgba(213, 195, 173, 0.14); border-radius: 2px;
  margin-bottom: 14px;
}
.threshold-bar span {
  position: absolute; inset: 0 auto 0 0; background: var(--ash-lit); border-radius: 2px;
  transition: width 420ms var(--ease);
}
.threshold-bar i {
  position: absolute; right: 0; top: 9px;
  font-style: normal; font-size: 10px; letter-spacing: 0.12em; color: var(--dim-dark);
}
.threshold p { font-size: 14px; color: var(--dim); }
.threshold.is-met .threshold-bar span { background: var(--salt); }
.threshold.is-met p { color: var(--salt); }

/* -------------------------------------------------------------- colophon */

.colophon { border-top: 1px solid var(--hair); padding: clamp(40px, 5vw, 70px) clamp(20px, 4vw, 56px) clamp(96px, 10vw, 130px); }
.colophon-in { max-width: 1360px; margin: 0 auto; }
.colophon-line { margin-top: 14px; font-size: 15px; color: var(--dim); max-width: 46ch; }
.credits { margin-top: clamp(26px, 3vw, 40px); display: grid; gap: 12px; max-width: 96ch; }
.credits p { font-size: 12px; line-height: 1.6; color: var(--dim-dark); }
.credits b { color: var(--dim); font-weight: 500; }

/* ------------------------------------------------------------------- bag */

.bag {
  position: fixed; right: clamp(14px, 3vw, 34px); bottom: clamp(14px, 3vw, 30px);
  z-index: 40; width: min(400px, calc(100vw - 28px));
  border: 1px solid var(--hair); border-radius: 3px;
  background: rgba(24, 20, 17, 0.94);
  backdrop-filter: blur(14px);
  box-shadow: 0 20px 60px rgba(0, 0, 0, 0.5);
}
.bag-tab {
  display: flex; align-items: center; gap: 14px; width: 100%;
  appearance: none; background: none; border: 0; padding: 14px 18px; cursor: pointer;
}
.bag-word { font-size: 12px; letter-spacing: 0.22em; text-transform: uppercase; }
.bag-count {
  min-width: 22px; height: 22px; padding: 0 6px; border-radius: 11px;
  display: inline-flex; align-items: center; justify-content: center;
  background: var(--ash); color: var(--kiln); font-size: 12px; font-weight: 600;
}
.bag-total { margin-left: auto; font-family: var(--serif); font-size: 18px; color: var(--ash-lit); }
.bag-tab:hover { background: rgba(213, 195, 173, 0.05); }
.bag.is-open .bag-tab { border-bottom: 1px solid var(--hair); }

.bag-panel { padding: 4px 18px 16px; max-height: min(58vh, 460px); overflow-y: auto; }
.bag-empty { padding: 12px 0; font-size: 14px; color: var(--dim-dark); }
.bag-lines { list-style: none; margin: 0; padding: 0; }
.bag-lines li {
  display: grid;
  grid-template-columns: 34px minmax(0, 1fr) auto;
  grid-template-areas: 'img name sum' 'img qty remove';
  gap: 2px 12px; align-items: center;
  padding: 12px 0; border-bottom: 1px solid var(--hair);
}
.bag-lines img { grid-area: img; width: 34px; height: 34px; border-radius: 2px; object-fit: cover; }
.bag-name { grid-area: name; font-size: 14px; }
.bag-name em { font-style: normal; color: var(--dim); }
.bag-qty { grid-area: qty; font-size: 12px; color: var(--dim-dark); }
.bag-sum { grid-area: sum; font-family: var(--serif); font-size: 16px; text-align: right; }
.bag-lines button {
  grid-area: remove; justify-self: end;
  appearance: none; background: none; border: 0; padding: 0; cursor: pointer;
  font-size: 11px; letter-spacing: 0.1em; text-transform: uppercase; color: var(--dim-dark);
  border-bottom: 1px solid transparent;
}
.bag-lines button:hover { color: var(--iron-lit); border-bottom-color: var(--iron-lit); }
.bag-foot { display: flex; justify-content: space-between; align-items: baseline; padding-top: 14px; }
.bag-foot span { font-size: 12px; letter-spacing: 0.18em; text-transform: uppercase; color: var(--dim-dark); }
.bag-foot b { font-family: var(--serif); font-weight: 400; font-size: 24px; }
.bag-ship { margin-top: 4px; font-size: 12px; color: var(--dim-dark); text-align: right; }

/* -------------------------------------------------------------- 860 down */

@media (max-width: 860px) {
  :root { --pxmm: 0.92; }
  .detail { grid-template-columns: 1fr; gap: 24px; }
  .glaze-row { grid-template-columns: 1fr; gap: 34px; }
  .glaze-note { min-height: 0; }
  .care-in { grid-template-columns: 1fr; }
  .notes-row { grid-template-columns: 1fr; gap: 32px; }
  .terms-in { grid-template-columns: 1fr; }
  .figures { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .figures > div:nth-child(2n) { border-right: 0; }
  .making-text { columns: 1; }
  .firing-track { padding-left: clamp(20px, 4vw, 56px); }

  /* the bag docks to the bottom edge on a phone */
  .bag {
    right: 0; left: 0; bottom: 0; width: 100%;
    border-radius: 0; border-left: 0; border-right: 0; border-bottom: 0;
  }
  .bag-panel { max-height: 52vh; }
}

@media (max-width: 480px) {
  :root { --pxmm: 0.78; }
  .masthead { padding-top: 40px; }
  .shelf-head { flex-direction: column; gap: 8px; }
  .care-table td { width: 26%; }
  .figures { grid-template-columns: 1fr 1fr; gap: 12px; }
  .figures b { font-size: 27px; }
}

@media (prefers-reduced-motion: reduce) {
  * { animation-duration: 1ms !important; animation-iteration-count: 1 !important; transition-duration: 1ms !important; }
  .glaze:hover figure img { transform: none; }
}

