    await p.waitForTimeout(700);
    await p.screenshot({path:`.scratch/shots/d-fire-${i}.png`});
  }
  await p.locator('#making').scrollIntoViewIfNeeded(); await p.waitForTimeout(600);
  await p.screenshot({path:'.scratch/shots/d-making.png'});
  await p.locator('#care').scrollIntoViewIfNeeded(); await p.waitForTimeout(600);
  await p.screenshot({path:'.scratch/shots/d-care.png'});
  await p.locator('#terms').scrollIntoViewIfNeeded(); await p.waitForTimeout(600);
  await p.screenshot({path:'.scratch/shots/d-terms.png'});
});
await page(390,844,'mobile',async p=>{
  await p.screenshot({path:'.scratch/shots/m-full.png',fullPage:true});
});
await b.close();
console.log(errs.length?'ERRORS:\n'+errs.join('\n'):'no console/network errors');
EOF
